import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);
import * as projectRepo from "@/server/repositories/project-repository";
import * as pmRepo from "@/server/repositories/project-member-repository";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("private", () => {
  it("works", async () => {
    const t = await createTenant("priv");
    const priv = await projectRepo.insertProject({
      orgId: t.org.id, name: "Secret", slug: "secret", key: "SEC", description: null,
      visibility: "private", leadId: t.userIds.admin, color: "#6366f1", targetDate: null,
    });
    const issue = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, priv.id, { title: "hidden" }));
    const comment = await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "hi", parentId: null, mentionedUserIds: [] } as never);
    await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { title: "visible" }));
    const m = t.actors.member;
    expect(await projectService.canViewProject(m, priv)).toBe(false);
    expect(await projectService.canViewProject(t.actors.admin, priv)).toBe(true);
    expect(await projectService.canViewProject({ ...t.actors.viewer, isPlatformStaff: true }, priv)).toBe(true);
    await expect(projectService.getProject(m, t.org.id, "secret")).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.getIssue(m, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.getBoard(t.actors.viewer, t.org.id, priv.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.getThread(m, t.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.deleteComment(m, { orgId: t.org.id, commentId: comment.id } as never)).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.createIssue(t.actors.viewer, issueInput(t.org.id, priv.id))).rejects.toBeInstanceOf(NotFoundError);
    await expect(projectService.archiveProject(m, { orgId: t.org.id, projectId: priv.id, archiveIssues: true } as never)).rejects.toBeInstanceOf(NotFoundError);
    const list = await issueService.listIssues(m, { orgId: t.org.id, limit: 50, cursor: null } as never);
    expect(list.items.map((i) => i.title)).toEqual(["visible"]);
    expect(list.total).toBe(1);
    const projects = await projectService.listProjects(m, { orgId: t.org.id, limit: 50, cursor: null } as never);
    expect(projects.total).toBe(1);
    const all = await projectService.listProjects(t.actors.owner, { orgId: t.org.id, limit: 50, cursor: null } as never);
    expect(all.total).toBe(2);
    await pmRepo.addProjectMember(t.org.id, priv.id, m.userId);
    expect((await issueService.listIssues(m, { orgId: t.org.id, limit: 50, cursor: null } as never)).total).toBe(2);
    expect((await projectService.getProject(m, t.org.id, "secret")).project.id).toBe(priv.id);
    await pmRepo.removeProjectMember(t.org.id, priv.id, m.userId);
    await expect(projectService.getProject(m, t.org.id, "secret")).rejects.toBeInstanceOf(NotFoundError);
    await projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: priv.id, leadId: m.userId } as never);
    expect((await projectService.listProjects(m, { orgId: t.org.id, limit: 50, cursor: null } as never)).total).toBe(2);
  });
});
